//! Clip timing operations: trims and rate changes with source and action bounds.

use crate::edit_clip::clip_end;
use crate::edit_speed_profile::profile_factors;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::source_advanced_through;
use crate::time::Ticks;

/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
/// #41). The app reads it through `rc_speed_limits` and never retypes it.
pub(crate) const SPEED_MIN: f64 = 0.1;
pub(crate) const SPEED_MAX: f64 = 1000.0;

/// The fastest a clip's audio still plays, in both pitch modes (spec §11
/// #190, the owner's decision of 2026-10-01). Above it the plan leaves the
/// clip's audio segment out (`evaluate.rs`); the video still runs to
/// `SPEED_MAX`. Chosen with a margin below a measured stall: an h264
/// export's loudness pass never finishes for a keep-pitch clip that starts
/// its audio track from ×15, nor in either mode from about ×20; ×12 and ×14
/// finish. B52a's mixer limits (×24 spectral, ×32 varispeed) hold only for
/// the mixer and an audio-only export, and are not the product's ceiling.
pub(crate) const AUDIO_SPEED_MAX: f64 = 12.0;

/// Every number about speed, as `rc_speed_limits` publishes it:
/// `{"min":0.1,"max":1000.0,"audio_max":12.0}`.
pub(crate) fn speed_limits() -> serde_json::Value {
    serde_json::json!({
        "min": SPEED_MIN,
        "max": SPEED_MAX,
        "audio_max": AUDIO_SPEED_MAX,
    })
}

impl Project {
    /// Moves the clip's start edge to `to`, advancing the source in point
    /// by `(to - start) × speed` so the frame under the edge does not move
    /// (spec §6).
    ///
    /// Clamped to the source bound — `to ≥ start - in/speed` snapped UP to
    /// a frame, `source_window.rs`'s `earliest_start_on_grid` (spec §11,
    /// D4-5) — and to leaving at least one frame of clip. Actions are
    /// deliberately left alone: clip-relative, rebasing would drop or bake
    /// whatever fell off the front, which is lossy and makes trimming back
    /// out not an identity. On a RAMPED clip the actions keep their clip
    /// time too, so `in` advances by round(S(Δ)) moving in and at the base
    /// rate moving out, and the edge is held where the clip still fits its
    /// media (`front_edge_held`, spec §11 SR-18 (c)): what plays after the
    /// new start can change. `text.words` are the opposite, on purpose
    /// (spec §11, W-3): a word is anchored to speech that stays where it is
    /// on the timeline, so every word is rebased by the trim's delta and a
    /// word trimmed off the front keeps its (negative) time. A graphic's
    /// `in` advances by the same delta (road map 10's G-9), with no speed
    /// and no head bound, never below 0.
    ///
    /// Without `alone`, a linked partner whose start is this clip's is
    /// trimmed to the same `to` after it, by its own clamps; with it, the
    /// clip moves alone — the J-cut (spec §11 AU-93, `carried_edge`).
    pub fn trim_start(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start,
            |project, id| project.trim_start_one(id, to),
        )
    }

    fn trim_start_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let end = clip_end(&target);
        let latest = end.saturating_sub(self.frame());
        let mut to = self.snapped(to).min(latest).max(0);

        if let Some(earliest) = self.earliest_start_on_grid(&target) {
            to = to.max(earliest.max(0));
        }
        // A ramped clip's edge is held where the clip still fits its media
        // (spec §11 SR-18 (c)); a constant clip's is `to` as clamped.
        let to = self.front_edge_held(&target, to);
        // The two clamps can cross when the source has almost nothing left
        // in front: then there is no legal new start, so nothing happens.
        if to > latest || to == target.start {
            return Ok(Outcome::Identity);
        }

        let delta = to.saturating_sub(target.start);
        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, delta);
        moved.start = to;
        moved.duration = end.saturating_sub(to);
        moved.graphic = graphic_advanced(target.graphic.as_ref(), delta);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, delta);
        }
        self.commit_replacements(vec![moved])
    }

    /// Moves the clip's end edge to `to`, clamped to the source's remaining
    /// length (media sources) and to at least one frame of clip (spec §6).
    /// The source in point and the actions are untouched. The bound is
    /// `source_window.rs`'s `latest_end_on_grid`, measured at this clip's
    /// OWN start: the last frame at or before the end of the file, and
    /// never the one past it (spec §11, #22 and D4-2). A ramped clip's bound
    /// reads its map on past the end (S∞, spec §11 SR-18 (a)). A graphic's
    /// `length` is untouched: null follows the new end, a number stays (G-9).
    /// `alone` is `trim_start`'s: without it a linked partner ending where
    /// this clip ends follows; with it, the L-cut (spec §11 AU-93).
    pub fn trim_end(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| clip_end(partner) == clip_end(target),
            |project, id| project.trim_end_one(id, to),
        )
    }

    fn trim_end_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let earliest = target.start.saturating_add(self.frame());
        let mut to = self.snapped(to).max(earliest);
        if let Some(latest) = self.latest_end_on_grid(&target) {
            to = to.min(latest);
        }
        if to < earliest || to == clip_end(&target) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.duration = to.saturating_sub(target.start);
        self.commit_replacements(vec![moved])
    }

    /// Drags the clip's end edge to `to_end` by changing its SPEED, not the
    /// source range it shows: `speed = source_len / (to_end - start)`
    /// (spec §6). Media sources only.
    ///
    /// An IDENTITY when the new length is under a frame or the resulting rate
    /// falls outside `SPEED_MIN`–`SPEED_MAX`; refused only when the placement
    /// breaks the overlap rule. Actions keep their clip-relative fraction.
    ///
    /// On a RAMPED clip the whole rate profile scales by f = D ÷ (to_end −
    /// start) through `scaled_profile`, so the ramp keeps its shape and its
    /// window; an f that would take any rate the clip names past the limits
    /// (`profile_factors`) changes nothing (spec §11 SR-19 (a), (b)).
    /// Refused on a linked clip (spec §11 AU-94).
    pub fn rate_stretch(&self, clip: u32, to_end: Ticks) -> Result<Outcome, String> {

/// An editable TIMECODE — the Clip tab's In and Out. `OptionFieldControl` is
/// a number with a unit and would spell 4.5 seconds "4.50 s"; a clip's edges
/// are read against the ruler, so they are spelled the way the ruler and the
/// toolbar spell them.
///
/// Parsing is the core's (`ReelTime.parse`), so `1:23`, `83.5` and `1:23:04`
/// mean here what they mean in the toolbar's field — and, exactly as there,
/// text it refuses beeps and the field snaps back rather than committing a
/// guess. A trim the CORE refuses beeps too, from `applyEdit`; nothing here
/// clamps a value into range on the user's behalf.
final class InspectorTimecodeField: NSTextField, OptionControl, NSTextFieldDelegate {
    private let read: () -> Ticks
    private let write: (Ticks) -> Void
    private let fps: () -> Fps
    private let frames: () -> Bool
    private let onEdit: () -> Void

    init(
        read: @escaping () -> Ticks, write: @escaping (Ticks) -> Void,
        fps: @escaping () -> Fps, frames: @escaping () -> Bool,
        onEdit: @escaping () -> Void
    ) {
        self.read = read
        self.write = write
        self.fps = fps
        self.frames = frames
        self.onEdit = onEdit
        super.init(frame: .zero)
        DSField.style(self, height: DS.controlHeight, radius: DS.controlRadius, font: DS.mono(11))
        translatesAutoresizingMaskIntoConstraints = false
        widthAnchor.constraint(equalToConstant: 104).isActive = true
        delegate = self
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorTimecodeField does not support NSCoder")
    }

    private var formatted: String {
        ReelTime.format(read(), fps: fps(), frames: frames())
    }

    func refresh() {
        // Skipped while the field is being typed into, or the value it is
        // about to commit would be overwritten by the one it replaces.
        guard currentEditor() == nil else { return }
        let value = formatted
        if stringValue != value { stringValue = value }
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        guard stringValue != formatted else { return }
        guard let ticks = ReelTime.parse(stringValue, fps: fps()) else {
            NSSound.beep()
            // Set directly rather than through `refresh()`: the field editor
            // may still be attached here, and `refresh()` would defer to it.
            stringValue = formatted
            return
        }
        write(ReelTime.snapToFrame(ticks, fps: fps()))
        onEdit()
    }
}

/// A section's one-line note — "Editing action 2's end state" (§4.3). Hides
/// itself when the closure returns nil, so a section pays nothing for a note
/// it does not currently have. With `wraps` it is a sentence of several lines
/// at the panel's width instead (the Motion and Speed notes, the Clip tab's
/// matte note), measured at its own width in `layout()`.
final class InspectorNoteLabel: NSTextField, OptionControl {
    let wraps: Bool
    private let note: () -> String?

    init(wraps: Bool = false, note: @escaping () -> String?) {
        self.wraps = wraps
        self.note = note
        super.init(frame: .zero)
        isEditable = false
        isBordered = false
        isBezeled = false
        drawsBackground = false
        font = DS.sans(11)
        textColor = DS.accent
        if wraps {
            usesSingleLineMode = false
            lineBreakMode = .byWordWrapping
            cell?.wraps = true
            maximumNumberOfLines = 0
            setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        } else {
            lineBreakMode = .byTruncatingTail
        }
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorNoteLabel does not support NSCoder")
    }

    /// A wrapping label needs its width to know its height.
    override func layout() {
        if wraps, preferredMaxLayoutWidth != bounds.width {
            preferredMaxLayoutWidth = bounds.width
        }
        super.layout()
    }

    func refresh() {
        let text = note()
        let shown = text ?? ""
        if stringValue != shown { stringValue = shown }
        isHidden = text == nil
    }
}

// MARK: - Multi-line text

//! The clip and action ops — spec §6, tables "Clips" and "Actions".
//!
//! One `impl Project` block holding clip construction, moves, copies and
//! deletes. Timing edits are in `edit_clip_timing.rs`; their placement commit
//! is in `edit_commit.rs`. The five property patches are the
//! OTHER half of the clip surface, `edit_props.rs`'s, policed by the range
//! checks of `props_check.rs`: this file decides where a clip sits, that one
//! what it looks like. The action ops, which were here, are `edit_action.rs`;
//! the transition ops, which were here too, are `edit_transition.rs`; and
//! `split_clip` with its two helpers, which every splitter in the crate
//! routes through, is `edit_split.rs` — a split is not a placement but a
//! question about what the SECOND clip inherits, and road map 5's E2 added
//! a rule to it. Detach Audio and `set_enabled`, a clip's two halves, are
//! `edit_detach.rs`'s.
//! `edit.rs` dispatches to all of them by name; nothing here knows about JSON
//! op envelopes, and nothing here mutates `self` — an edit clones, changes
//! the clone, and hands it back (spec §5.5).
//!
//! Three rules run through all of it:
//!
//! 1. **Every tick argument is snapped to the canvas frame grid first**
//!    ([`Project::snapped`]), durations included. Nothing sub-frame ever
//!    reaches the model.
//! 2. **Placement is checked, never repaired.** A move, trim or duplicate
//!    that would break the overlap rule is REFUSED, in the rule's own
//!    sentence ([`Outcome::Refused`]) — the UI animates it back. The rule
//!    itself lives in `transition.rs` and is called, never restated, which
//!    is why the sentence the caller reads is the one the rule wrote.
//! 3. **Every op leaves the project valid.** [`Project::finish`] is the
//!    single exit: it answers [`Outcome::Identity`] when the result equals
//!    the input (no phantom undo step) and turns a broken invariant into
//!    `Err`.
//!
//! The pieces those three rules are made of — `snapped`, `frame`, the
//! `require_*` lookups, `selected_clips` and `clip_end` — are `pub(crate)`
//! so other edit modules obey the same rules by calling them. Placement
//! finalization and `finish` live in `edit_commit.rs`.
//! `add_text_clip`, `add_shape_clip` and `add_described_clip` are `edit_described.rs`'s.

use std::collections::HashMap;

use crate::edit_link::{pair_split_halves, relink_copies};
use crate::edit_split::split_clip;
use crate::model::{AudioProps, Clip, Media, MediaKind, Project, Source, Track, VideoProps};
use crate::outcome::Outcome;
use crate::time::{self, Ticks, TIMESCALE};

/// Default duration for a source with no source bound — text, shape, and an
/// image whose descriptor carries no duration. Five seconds is a common
/// title default and long enough to read.
pub(crate) const DEFAULT_CLIP_DURATION: Ticks = 5 * TIMESCALE;

// ---- clip helpers --------------------------------------------------------

pub(crate) fn clip_end(clip: &Clip) -> Ticks {
    clip.start.saturating_add(clip.duration)
}

// ---- the ops -------------------------------------------------------------

//! Slip and roll — spec §6 rows `slip` and `roll`.
//!
//! What separates these two from `edit_clip.rs`'s trims is that neither
//! changes how long the CUT is. A **slip** changes what a clip shows
//! without moving it: the window stays where it is on the timeline and the
//! film slides under it. A **roll** moves the frame two clips meet on
//! without moving anything else: one grows by exactly what the other loses.
//! They are what a cutter reaches for once the rough assembly is down, when
//! every following clip is already where it belongs and nothing may shift.
//!
//! Both are therefore *conservative* ops, and both are written to refuse
//! rather than approximate. A slip that has run out of source at one end
//! stops, and a slip that could not move at all is an identity — the
//! alternative is a drag that silently becomes a different, shorter edit
//! than the gesture asked for. A roll needs a hard cut to move: with a gap,
//! or with an overlap (which IS a transition, whose length is
//! `set_transition_duration`'s job), there is nothing here to roll.
//!
//! The arithmetic is `source_window.rs`'s — the three measurements of a
//! source window, the conversion into source ticks and the two last legal
//! positions all live there, and this module only clamps against them, so a
//! slip and a trim can never disagree about where a media ends.

use crate::edit_clip::clip_end;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::{source_advanced_through, timeline_to_source};
use crate::time::Ticks;

impl Project {
    /// Slides the source window under a fixed clip: what the clip shows
    /// changes, where it sits does not (spec §6).
    ///
    /// `delta` is TIMELINE ticks — the distance the gesture travelled — so
    /// the source moves by `delta × speed`, the same conversion
    /// `trim_start` makes when it advances `in`. A positive `delta` shows
    /// LATER material, which is the direction the drag reads: pulling the
    /// clip right pulls the film forward under the window.
    ///
    /// Clamped so the window stays inside the media — `in ≥ 0` at the head,
    /// `in + duration × speed ≤ media.duration` at the tail — and a slip
    /// the clamps reduce to nothing is an identity. On a RAMPED clip the
    /// delta is converted at the base rate and the tail clamp is
    /// `file − S(D)` (`last_in_point` reads S); the actions do not move
    /// (spec §11 SR-18 (d)).
    ///
    /// A `still` has one source TIME rather than a window, so it moves that
    /// instead, clamped inside the media the same way. Every other source
    /// has nothing to slip and is an `Err` under the non-media rule.
    ///
    /// **The source kind is decided FIRST**, before the delta is even
    /// measured. A text clip named for a slip is an invalid argument
    /// whatever the delta was, and letting a sub-frame delta short-circuit
    /// to an identity would answer "valid, changes nothing" to a call that
    /// was never valid — the one answer the non-media rule exists to stop
    /// the MCP agent being given.
    ///
    /// Nothing moves, so there is no overlap to check and no transition can
    /// be gained; the actions are clip-relative and stay exactly where they
    /// are.
    ///
    /// **A linked partner on an unlocked track slips with it**, by the
    /// smaller in magnitude of the two clamped amounts, so the sound stays
    /// on its picture (spec §11 AU-94).
    pub fn slip(&self, clip: u32, delta: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let delta = self.snapped(delta);
        let Some(own) = self.slip_amount(&target, delta)? else {
            return Ok(Outcome::Identity);
        };
        let partner = self
            .partner(clip)
            .filter(|p| self.track(p.track).is_some_and(|t| !t.locked))
            .cloned();
        let mut amount = own;
        if let Some(partner) = &partner {
            let theirs = self.slip_amount(partner, delta)?.unwrap_or(0);
            if theirs.abs() < amount.abs() {
                amount = theirs;
            }
        }
        if amount == 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in std::iter::once(clip).chain(partner.map(|p| p.id)) {
            if let Some(slot) = next.clip_mut(id) {
                slot.source = match &slot.source {
                    Source::Media {
                        media,
                        r#in,
                        reversed,
                    } => Source::Media {
                        media: *media,
                        r#in: r#in.saturating_add(amount),
                        reversed: *reversed,
                    },
                    Source::Still { media, at } => Source::Still {
                        media: *media,
                        at: at.saturating_add(amount),
                    },
                    other => other.clone(),
                };
            }
        }
        self.finish(next)
    }

    /// How far, in SOURCE ticks, a slip of `delta` timeline ticks moves
    /// `clip` once clamped inside its media; `None` when the move rounds to
    /// nothing before the clamp. `Err` for a source with nothing to slip,
    /// decided FIRST (the doc above).
    fn slip_amount(&self, clip: &Clip, delta: Ticks) -> Result<Option<Ticks>, String> {
        let (media, current) = match clip.source {
            Source::Media { media, r#in, .. } => (media, r#in),
            Source::Still { media, at } => (media, at),
            _ => return Err(format!("clip {} is not a media clip", clip.id)),
        };
        // Timeline ticks to source ticks, at this clip's rate. A sub-tick
        // move at a very slow speed rounds to nothing, which is a refusal
        // and not an edit.
        let moved_by = timeline_to_source(delta, clip.speed);
        if moved_by == 0 {
            return Ok(None);
        }

        // The last legal position of what the clip shows: a window is
        // pushed against the tail of the file, a still stops one frame
        // short of it. Both are `source_window.rs`'s, which is also where
        // the reasons for the two shapes are written down.
        let media = self.require_media(media)?;
        let last = match clip.source {
            Source::Still { .. } => self.last_still_time(media),
            _ => self.last_in_point(clip, media),
        };
        let slipped = current.saturating_add(moved_by).clamp(0, last);
        Ok(Some(slipped.saturating_sub(current)))
    }

    /// Moves a hard cut: this clip's start and its predecessor's end both
    /// become `to`, and nothing else in the timeline moves (spec §6).
    ///
    /// The predecessor is the clip on the same track that ends EXACTLY at
    /// this clip's start. With no such clip the op refuses, naming the
    /// track and the start (spec §11 #88) — a gap has no cut to roll, and an
    /// overlap is a transition whose length `set_transition_duration` owns.
    ///
    /// `to` is clamped four ways, one pair per side: each clip keeps at
    /// least one frame, this clip may only reach back as far as its own
    /// source head allows (it grows at the FRONT, with front-trim
    /// semantics, so `in` follows), and the predecessor may only reach
    /// forward as far as its remaining source allows (it grows at the END,
    /// a plain end trim, so its `in` does not move). A `to` the clamps
    /// leave equal to the current cut is an identity, and so is a pair of
    /// clamps that cross — a cut with no legal position is not one this op
    /// can move.
    ///
    /// On a RAMPED clip this clip's `in` advances through its map, and the
    /// cut is held where it still fits its media (`front_edge_held`); the
    /// predecessor's bound reads its map on past its end (spec §11 SR-18
    /// (a), (c)).
    ///
    /// Neither clip's outer edge moves, so the pair still abuts exactly and
    /// no transition can be gained; the actions on both are clip-relative
    /// and stay where they are, as they do for a trim. This clip's
    /// `text.words` are rebased by the move, as `trim_start` rebases them
    /// (spec §11, W-3): a word stays on the speech it times. Its
    /// `graphic.in` advances by the move as `trim_start`'s does, and the
    /// predecessor's `length` is untouched (road map 10's G-9).
    ///
    /// Without `alone`, a linked partner whose start is this clip's and
    /// which has a hard-cut predecessor of its own is rolled to the same
    /// `to` after it (spec §11 AU-93, `carried_edge`); with it, the clip's
    /// cut moves alone.
    pub fn roll(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        let hard_cut = |partner: &Clip| {
            self.clips_on_track(partner.track)
                .iter()
                .any(|c| c.id != partner.id && clip_end(c) == partner.start)
        };
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start && hard_cut(partner),
            |project, id| project.roll_one(id, to),
        )
    }

    fn roll_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Some(previous) = self
            .clips_on_track(target.track)
            .into_iter()
            .find(|c| c.id != target.id && clip_end(c) == target.start)
            .cloned()
        else {
            return Ok(Outcome::Refused(format!(
                "no clip on track {} ends where clip {clip} begins ({}), so there is no cut \
                 to roll",
                target.track, target.start
            )));
        };

        let frame = self.frame();
        let mut earliest = previous.start.saturating_add(frame);
        let mut latest = clip_end(&target).saturating_sub(frame);
        if let Some(start) = self.earliest_start_on_grid(&target) {
            earliest = earliest.max(start.max(0));
        }
        if let Some(end) = self.latest_end_on_grid(&previous) {
            latest = latest.min(end);
        }
        // The two source bounds arrive on the grid (`source_window.rs`
        // snaps each inward, and this pair is where that rule came from),
        // but the one-frame bounds are measured from the clips' own starts,
        // which a hand-written document may put off it. So both are snapped
        // INWARD again — up at the bottom, down at the top — and the cut
        // lands on a frame that is still inside the source both clips have.
        let earliest = self.snapped_up(earliest);
        let latest = self.snapped_down(latest);
        if earliest > latest {
            return Ok(Outcome::Identity);
        }
        let to = self.snapped(to).clamp(earliest, latest);
        // A ramped target's front edge is held where it still fits its
        // media, as `trim_start`'s is (spec §11 SR-18 (c)).
        let to = self.front_edge_held(&target, to);
        if to == target.start {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, to.saturating_sub(target.start));
        moved.graphic = graphic_advanced(target.graphic.as_ref(), to.saturating_sub(target.start));
        moved.start = to;
        moved.duration = clip_end(&target).saturating_sub(to);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, to.saturating_sub(target.start));
        }

        let mut grown = previous.clone();
        grown.duration = to.saturating_sub(previous.start);

        // The clamps make this unreachable for the pair itself; it is here
        // because every placement op checks, and because a track that
        // already held something the rule dislikes should not have it made
        // worse by an edit that thought it was safe.
        if let Err(why) =
            self.check_overlap_rule(&[moved.clone(), grown.clone()], target.track, &[])
        {
            return Ok(Outcome::Refused(why));
        }

        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(target.id) {
            *slot = moved;
        }
        if let Some(slot) = next.clip_mut(previous.id) {
            *slot = grown;
        }
        self.finish(next)
    }
}
