            #selector(toggleTrackMuted(_:)), #selector(toggleTrackLocked(_:)):
            return currentTrack != nil
        case #selector(nextMarker(_:)), #selector(previousMarker(_:)):
            return !document.project.snapshot.markers.isEmpty
        default:
            return nil
        }
    }
